const zennItems = $('FetchZenn').all().map(item => ({
  title: (item.json.title || '').substring(0, 200),
  url: item.json.link || '',
  source: 'Zenn',
  category: '\u30c6\u30c3\u30af',
  date: (item.json.isoDate || item.json.pubDate || new Date().toISOString()).substring(0, 10),
  summary: (item.json.contentSnippet || item.json['content:encodedSnippet'] || '').replace(/<[^>]*>/g, '').substring(0, 300)
}));

const hnItems = $('FetchHN').all().map(item => ({
  title: (item.json.title || '').substring(0, 200),
  url: item.json.link || '',
  source: 'Hacker News',
  category: '\u30c6\u30c3\u30af',
  date: (item.json.isoDate || item.json.pubDate || new Date().toISOString()).substring(0, 10),
  summary: (item.json.contentSnippet || item.json['content:encodedSnippet'] || '').replace(/<[^>]*>/g, '').substring(0, 300)
}));

const allItems = [...zennItems.slice(0, 10), ...hnItems.slice(0, 10)];

return allItems.map(item => {
  const requestBody = JSON.stringify({
    parent: { database_id: '2ff2570f-e49f-817d-8288-e7c8667641a9' },
    properties: {
      '\u30bf\u30a4\u30c8\u30eb': { title: [{ text: { content: item.title } }] },
      'URL': { url: item.url || null },
      '\u30ab\u30c6\u30b4\u30ea': { select: { name: item.category } },
      '\u30bd\u30fc\u30b9': { rich_text: [{ text: { content: item.source } }] },
      '\u65e2\u8aad': { checkbox: false },
      '\u65e5\u4ed8': { date: { start: item.date } },
      '\u8981\u7d04': { rich_text: [{ text: { content: item.summary } }] }
    }
  });
  return { json: { requestBody, title: item.title, source: item.source } };
});
